"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["21501"],{14134(e){e.exports=JSON.parse('{"id":"F376","slug":"raroc-limit-utilization","name":"RAROC and Risk Limit Utilization","subject":"Risk Management","section":"Risk","topic":"Risk appetite and limits","level":"Intermediate","aliases":["risk adjusted return on capital","risk appetite","VaR limit","hurdle rate"],"formula":{"latex":"RAROC=\\\\frac{\\\\text{Revenue}-\\\\text{Costs}-EL}{\\\\text{Economic capital}},\\\\quad \\\\text{Utilization}=\\\\frac{VaR}{\\\\text{Limit}}","also":[],"text":"RAROC = (Revenue - Costs - Expected loss) / Economic capital; Limit utilization = Risk used / Limit"},"symbols":[{"symbol":"EL","meaning":"Expected loss","unit":"money"},{"symbol":"Economic capital","meaning":"Capital held against unexpected losses","unit":"money"},{"symbol":"Limit","meaning":"The maximum risk the board allows for a desk or business line","unit":"money"}],"when_to_use":"Use it to compare businesses by return per unit of risk, and to track a limit set by the risk appetite. A business is creating value if RAROC beats the hurdle rate. Utilization near 100% means the desk has little room left.","worked_example":{"problem":"A business earns revenue of 120 and has costs of 60 and expected loss of 15. It uses 250 of economic capital and the hurdle rate is 12%. Its VaR is 4.2 against a limit of 5.0.","inputs":{"rev":120,"cost":60,"el":15,"ec":250,"hurdle":12,"var":4.2,"limit":5},"steps":[{"label":"RAROC = (revenue - costs - EL) / economic capital","working":"(120-60-15) / 250","value":"18.0%"},{"label":"Excess over the hurdle","working":"0.18-0.12","value":"6.0%"},{"label":"Limit utilization = VaR / limit","working":"var / 5","value":"84.0%"},{"label":"Headroom = limit - VaR","working":"5-var","value":"0.80"}],"answer":"RAROC is 18.0%, above the hurdle of 12%, so the business adds value beyond its risk cost, with 6.0% of excess return. The VaR limit is 84.0% used, leaving headroom of 0.80."},"calculator":{"available":true,"inputs":[{"id":"rev","label":"Revenue","unit":"money","type":"number","default":120,"hint":""},{"id":"cost","label":"Costs","unit":"money","type":"number","default":60,"hint":""},{"id":"el","label":"Expected loss","unit":"money","type":"number","default":15,"hint":""},{"id":"ec","label":"Economic capital","unit":"money","type":"number","default":250,"hint":""},{"id":"hurdle","label":"Hurdle rate","unit":"%","type":"number","default":12,"hint":""},{"id":"var","label":"Current VaR","unit":"money","type":"number","default":4.2,"hint":""},{"id":"limit","label":"VaR limit","unit":"money","type":"number","default":5,"hint":""}],"checks":[{"expr":"ec>0 and limit>0","message":"Economic capital and the limit must be above zero."}],"steps":[{"id":"raroc","label":"RAROC = (revenue - costs - EL) / economic capital","expr":"(rev-cost-el)/ec","format":"pct1"},{"id":"excess","label":"Excess over the hurdle","expr":"raroc-hurdle","format":"pct1"},{"id":"util","label":"Limit utilization = VaR / limit","expr":"var/limit","format":"pct1"},{"id":"room","label":"Headroom = limit - VaR","expr":"limit-var","format":"num2"}],"results":["raroc","util"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"raroc":0.18,"excess":0.06,"util":0.84,"room":0.8}},"finder":{"finds":"Return on risk capital and how much of a risk limit is used","needs":"Revenue, costs, expected loss, economic capital, VaR, limit"},"related":[{"slug":"expected-unexpected-loss","name":"Expected and Unexpected Credit Loss"},{"slug":"return-on-equity","name":"Return on Equity (ROE)"},{"slug":"var-parametric","name":"Value at Risk: Parametric (Variance-Covariance)"}],"related_ids":["F384","F128","F378"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>R</mi><mi>A</mi><mi>R</mi><mi>O</mi><mi>C</mi><mo>=</mo><mfrac><mrow><mtext>Revenue</mtext><mo>\u2212</mo><mtext>Costs</mtext><mo>\u2212</mo><mi>E</mi><mi>L</mi></mrow><mtext>Economic\xa0capital</mtext></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Utilization</mtext><mo>=</mo><mfrac><mrow><mi>V</mi><mi>a</mi><mi>R</mi></mrow><mtext>Limit</mtext></mfrac></mrow><annotation encoding=\\"application/x-tex\\">RAROC=\\\\frac{\\\\text{Revenue}-\\\\text{Costs}-EL}{\\\\text{Economic capital}},\\\\quad \\\\text{Utilization}=\\\\frac{VaR}{\\\\text{Limit}}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"r-squared","name":"R-Squared (Coefficient of Determination)"},"next":{"slug":"fed-funds-futures-probability","name":"Rate Expectations from Policy Rate Futures"},"lesson":null,"total":522}')}}]);